<?php
declare(strict_types=1);require __DIR__.'/app/bootstrap.php';if(is_file(__DIR__.'/app/access_control_v1300.php'))require_once __DIR__.'/app/access_control_v1300.php';require_once __DIR__.'/app/services_v1380.php';sk1380_require_login('/request-service.php');$cats=sk1380_categories();$preProvider=(int)($_GET['provider']??0);$preService=(int)($_GET['service']??0);$off=$preService?sk1380_offering($preService,true):null;$err='';if($_SERVER['REQUEST_METHOD']==='POST'){try{sk1380_csrf_check();$cid=(int)($_POST['category_id']??0);$title=trim((string)($_POST['title']??''));$desc=trim((string)($_POST['description']??''));$addr=trim((string)($_POST['address_text']??''));$area=trim((string)($_POST['area']??''));$urg=in_array($_POST['urgency']??'normal',['normal','fast'],true)?$_POST['urgency']:'normal';if(!sk1380_category($cid)||$title===''||$desc===''||$addr==='')throw new RuntimeException('Service, title, job details and address are required.');$max=max(1,(int)sk1380_setting('services_max_open_requests','10'));$q=sk1380_db()->prepare('SELECT COUNT(*) FROM service_requests_v1380 WHERE tenant_id=? AND customer_user_id=? AND status IN("open","quoted")');$q->execute([sk1380_tid(),sk1380_uid()]);if((int)$q->fetchColumn()>=$max)throw new RuntimeException('Please close an existing open request before posting another one.');$q=sk1380_db()->prepare('INSERT INTO service_requests_v1380(tenant_id,customer_user_id,category_id,preferred_provider_id,title,description,address_text,area,preferred_date,preferred_time,urgency,budget_min,budget_max,status,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,"open",NOW(),NOW())');$pref=(int)($_POST['preferred_provider_id']??0);if($pref>0&&!sk1380_provider_by_id($pref,true))$pref=0;$q->execute([sk1380_tid(),sk1380_uid(),$cid,$pref?:null,$title,$desc,$addr,$area?:null,($_POST['preferred_date']??'')?:null,trim((string)($_POST['preferred_time']??''))?:null,$urg,($_POST['budget_min']??'')!==''?(float)$_POST['budget_min']:null,($_POST['budget_max']??'')!==''?(float)$_POST['budget_max']:null]);$rid=(int)sk1380_db()->lastInsertId();if((int)($_POST['preferred_provider_id']??0)>0)sk1380_db()->prepare('INSERT INTO service_moderation_log_v1380(tenant_id,entity_type,entity_id,actor_user_id,action_key,note,created_at) VALUES(?,"request",?,?,"preferred_provider",?,NOW())')->execute([sk1380_tid(),$rid,sk1380_uid(),(string)(int)$_POST['preferred_provider_id']]);header('Location: /my-services.php?request='.$rid);exit;}catch(Throwable $e){$err=$e->getMessage();}}sk1380_shell('Post a Service Request','request');?><section class="form-hero"><span class="eyebrow">REQUEST A LOCAL SERVICE</span><h1>Kaam batayein. Local providers quote bhejein.</h1><p>Address sirf job matching/booking ke liye use hota hai; public provider listing par customer address show nahi hota.</p></section><?php if($err):?><div class="notice err"><?=sk1380_h($err)?></div><?php endif;?><form method="post" class="pro-form"><input type="hidden" name="_csrf" value="<?=sk1380_h(sk1380_csrf())?>"><input type="hidden" name="preferred_provider_id" value="<?=$preProvider?>"><label>Service category<select name="category_id" required><option value="">Choose service</option><?php foreach($cats as $c):?><option value="<?=$c['id']?>" <?=($off&&$off['category_id']==$c['id'])||((int)($_POST['category_id']??0)==$c['id'])?'selected':''?>><?=sk1380_h($c['icon'].' '.$c['name'])?></option><?php endforeach;?></select></label><label>What needs to be done?<input name="title" required value="<?=sk1380_h($_POST['title']??($off['title']??''))?>" placeholder="e.g. Ceiling fan is not working"></label><label>Job details<textarea name="description" rows="5" required><?=sk1380_h($_POST['description']??'')?></textarea></label><div class="two"><label>Full service address<textarea name="address_text" rows="3" required><?=sk1380_h($_POST['address_text']??'')?></textarea></label><label>Area / locality<input name="area" value="<?=sk1380_h($_POST['area']??'Shahkot')?>"></label></div><div class="three"><label>Preferred date<input type="date" name="preferred_date" value="<?=sk1380_h($_POST['preferred_date']??'')?>"></label><label>Preferred time<input name="preferred_time" placeholder="e.g. 4 PM - 6 PM" value="<?=sk1380_h($_POST['preferred_time']??'')?>"></label><label>Urgency<select name="urgency"><option value="normal">Normal</option><option value="fast">Fast service requested</option></select></label></div><div class="two"><label>Budget from (optional)<input type="number" min="0" name="budget_min"></label><label>Budget to (optional)<input type="number" min="0" name="budget_max"></label></div><button class="btn">Post Request & Receive Quotes</button></form><?php sk1380_end();